-- CTRP raw rows for the Python feature notebook (notebooks/CTRP_features_in_python.ipynb), piece 2 of 6.
-- A plain SELECT: no calculation. Every item row of IM4 and IM7 declarations assessed after 2024-03-31 up to
-- 2024-09-30, for a 5% random sample of taxpayers (the same taxpayers in every piece: pmod(hash(TIN), 20) = 0).
-- Cleaning (cancelled, TIN format, APC 483, entry key, motor vehicles, repeated rows) is done in the notebook.
-- Run as ONE statement, download as CSV, save as data/python_features/raw_items_2.csv
-- GENERATED by the notebook builder settings (snapshot 2026-09-30, 36 months back).
SELECT v.instance_id, v.key_itm_nbr, v.assessment_dt_wid, v.taxpayer_tin, v.regime_cd, v.decl_status,
       v.cpc_cd, v.extended_proc_cd, v.hsc_cd, v.gds_org_cty, v.customs_value, v.net_weight,
       v.supplementary_qnty, v.tax_assessed, v.original_tax_amt, v.final_amt, v.top_up_flg,
       v.amendment_flg, v.clearance_station_cd, v.is_red_flg, v.is_yellow_flg, v.pay_status,
       v.preferential_treatment_flag, v.entry_num, v.dec_ref_yer, v.taxpayer_nm
FROM dm_modeled_ura_datascience.vw_cstm_AEO_model v
WHERE v.assessment_dt_wid >  '20240331'
  AND v.assessment_dt_wid <= '20240930'
  AND v.regime_cd IN ('IM4', 'IM7')
  AND pmod(hash(v.taxpayer_tin), 20) = 0
